package com.campus.student.api;
import java.time.Instant; import java.util.*; import com.campus.student.application.StudentManagementService; import com.campus.student.domain.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/v1/admin/students") public class AdminStudentController { private final StudentManagementService service; public AdminStudentController(StudentManagementService s){service=s;} @PostMapping public ResponseEntity<Response> create(Authentication a,@Valid @RequestBody Request r){Student s=service.create((UUID)a.getPrincipal(),r.studentNumber(),r.fullName(),r.email(),r.identityUserId(),r.organizationUnitId(),r.status());return ResponseEntity.created(ServletUriComponentsBuilder.fromCurrentRequest().path("/{studentId}").buildAndExpand(s.id()).toUri()).body(out(s));} @GetMapping public PageResponse list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(defaultValue="studentNumber,asc")String sort){if(page<0||size<1||size>100||(q!=null&&q.trim().codePointCount(0,q.trim().length())>100))throw new InvalidQueryParameterException();String[] parts=sort.split(",",-1);if(parts.length!=2||!Set.of("studentNumber","fullName","email","status","createdAt","updatedAt").contains(parts[0])||!(parts[1].equals("asc")||parts[1].equals("desc")))throw new InvalidQueryParameterException();StudentStatus requested;try{requested=status==null?null:StudentStatus.valueOf(status);}catch(IllegalArgumentException e){throw new InvalidQueryParameterException();}var result=service.search(new StudentSearch(page,size,q==null||q.trim().isEmpty()?null:q.trim(),requested,parts[0],parts[1].equals("asc")));return new PageResponse(result.content().stream().map(AdminStudentController::out).toList(),page,size,result.totalElements(),(int)Math.ceil((double)result.totalElements()/size));} @GetMapping("/{studentId}") public Response get(@PathVariable UUID studentId){return out(service.get(studentId));} @PutMapping("/{studentId}") public Response update(Authentication a,@PathVariable UUID studentId,@Valid @RequestBody UpdateRequest r){return out(service.update((UUID)a.getPrincipal(),studentId,r.studentNumber(),r.fullName(),r.email(),r.identityUserId(),r.organizationUnitId(),r.status(),r.expectedVersion()));} private static Response out(Student s){return new Response(s.id(),s.studentNumber(),s.fullName(),s.email(),s.identityUserId(),s.organizationUnitId(),s.status().name(),s.rowVersion(),s.createdAt(),s.updatedAt());} public record Request(@NotBlank String studentNumber,@NotBlank String fullName,String email,UUID identityUserId,@NotNull UUID organizationUnitId,StudentStatus status){} public record UpdateRequest(@NotBlank String studentNumber,@NotBlank String fullName,String email,UUID identityUserId,@NotNull UUID organizationUnitId,@NotNull StudentStatus status,@NotNull @PositiveOrZero Long expectedVersion){} public record Response(UUID id,String studentNumber,String fullName,String email,UUID identityUserId,UUID organizationUnitId,String status,long rowVersion,Instant createdAt,Instant updatedAt){} public record PageResponse(List<Response> content,int page,int size,long totalElements,int totalPages){} public static final class InvalidQueryParameterException extends RuntimeException{} }
